import { api } from './authService';

/**
 * FIX 1 : amenities ajoutées dans create() et update()
 * FIX 2 : status envoyé dans update() (champ @NotNull dans UpdateRoomRequest)
 * FIX 3 : status envoyé en UPPERCASE pour correspondre à l'enum Java RoomStatus
 *          (AVAILABLE, OCCUPIED)
 * FIX 4 : le frontend utilise price_per_night, le backend attend price
 *          → mapping explicite dans les deux sens
 */

/** Convertit le statut frontend en valeur enum backend */
const toBackendStatus = (status) => {
  const map = {
    available:   'AVAILABLE',
    occupied:    'OCCUPIED',
    maintenance: 'AVAILABLE',  // fallback : maintenance non supporté côté backend
  };
  if (!status) return 'AVAILABLE';
  return map[status.toLowerCase()] ?? status.toUpperCase();
};

const roomService = {
  /** GET /rooms */
  getAll: async (params = {}) => {
    const { data } = await api.get('/rooms', { params });
    return data?.data ?? data;
  },

  getAvailable: async ({ checkIn, checkOut } = {}) => {
    const { data } = await api.get('/rooms/available', {
      params: { checkIn, checkOut },
    });
    return data?.data ?? data;
  },

  getById: async (id) => {
    const { data } = await api.get(`/rooms/${id}`);
    return data?.data ?? data;
  },

  /**
   * POST /rooms
   * Champs envoyés :
   *   number, type (UPPERCASE), price, capacity, description, amenities
   */
  create: async (roomData) => {
    const payload = {
      number:      String(roomData.number).trim(),
      type:        roomData.type?.toUpperCase(),                    // ex: 'double' → 'DOUBLE'
      price:       Number(roomData.price_per_night) || Number(roomData.price) || 0,
      capacity:    Number(roomData.capacity) || 1,
      description: roomData.description || '',
      amenities:   Array.isArray(roomData.amenities) ? roomData.amenities : [],  // FIX amenities
    };
    const { data } = await api.post('/rooms', payload);
    return data?.data ?? data;
  },

  /**
   * PUT /rooms/{id}
   * FIX : status obligatoire (@NotNull dans UpdateRoomRequest)
   *        amenities transmises
   */
  update: async (id, roomData) => {
    const payload = {
      number:      String(roomData.number).trim(),
      type:        roomData.type?.toUpperCase(),
      price:       Number(roomData.price_per_night) || Number(roomData.price) || 0,
      capacity:    Number(roomData.capacity) || 1,
      status:      toBackendStatus(roomData.status),               // FIX status
      description: roomData.description || '',
      amenities:   Array.isArray(roomData.amenities) ? roomData.amenities : [],  // FIX amenities
    };
    const { data } = await api.put(`/rooms/${id}`, payload);
    return data?.data ?? data;
  },

  delete: async (id) => {
    const { data } = await api.delete(`/rooms/${id}`);
    return data?.data ?? data;
  },
};

export default roomService;
